/**
 * Replace every IPv6 firewall rule with the list sent, as setRules does for IPv4: every rule gets a new identifier (observed). It marks iptables dirty (observed). Returns the stored rules.
 * @summary Put the IPv6 firewall rules in a new order
 */
export const iptablesSetRules6 = (
  iptablesSetRules6Request: BodyType<IptablesSetRules6Request>,
  options?: SecondParameter<typeof rpcClient>,
  signal?: AbortSignal,
) => {
  return rpcClient<IptablesRuleList>(
    {
      url: `/rpc/Iptables/setRules6`,
      method: "POST",
      headers: { "Content-Type": "application/json" },
      data: iptablesSetRules6Request,
      signal,
    },
    options,
  );
};

